namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public List<int> Ratings { get; set; } = [];

    public double AverageRating =>
        Ratings.Count > 0 ? Math.Round(Ratings.Average(), 1) : 0;

    public int RatingCount => Ratings.Count;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple yet delicious pizza with fresh tomatoes, mozzarella, and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = [
                    "Preheat oven to 475°F (245°C) with a pizza stone inside.",
                    "Stretch the dough into a 12-inch round on a floured surface.",
                    "Spread crushed tomatoes evenly over the dough.",
                    "Tear mozzarella into pieces and distribute over the sauce.",
                    "Bake for 10-12 minutes until the crust is golden.",
                    "Top with fresh basil leaves and a drizzle of olive oil."
                ],
                Ratings = [5, 4, 5, 5, 4]
            },
            new Recipe
            {
                Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken pieces in a creamy, spiced tomato sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger", "Cumin", "Turmeric"],
                Steps = [
                    "Marinate chicken in yogurt, garam masala, and salt for at least 1 hour.",
                    "Grill or broil the chicken until charred and cooked through.",
                    "Sauté onion, garlic, and ginger in oil until softened.",
                    "Add spices and cook for 1 minute until fragrant.",
                    "Add tomato sauce and simmer for 15 minutes.",
                    "Stir in cream and the cooked chicken. Simmer 5 more minutes.",
                    "Serve over basmati rice with naan bread."
                ],
                Ratings = [5, 5, 4, 5]
            },
            new Recipe
            {
                Id = 3, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef tacos with fresh toppings.",
                Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
                Steps = [
                    "Brown the ground beef in a skillet over medium-high heat.",
                    "Add taco seasoning and water, simmer until thickened.",
                    "Warm tortillas in a dry skillet or microwave.",
                    "Fill tortillas with seasoned beef.",
                    "Top with lettuce, diced tomato, cheese, sour cream, and salsa."
                ],
                Ratings = [4, 4, 5, 3, 4]
            },
            new Recipe
            {
                Id = 4, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "A rich Roman pasta dish with eggs, cheese, and pancetta.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
                Steps = [
                    "Cook spaghetti in salted boiling water until al dente.",
                    "Crisp pancetta in a skillet until golden.",
                    "Whisk eggs and grated Pecorino together in a bowl.",
                    "Toss hot drained pasta with pancetta and rendered fat.",
                    "Remove from heat and quickly stir in the egg mixture.",
                    "Season generously with black pepper and serve immediately."
                ],
                Ratings = [5, 5, 5, 4, 5]
            },
            new Recipe
            {
                Id = 5, Title = "Pad Thai", Category = "Asian",
                Description = "Stir-fried rice noodles with shrimp, peanuts, and tangy sauce.",
                Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Green onions", "Peanuts", "Tamarind paste", "Fish sauce", "Sugar", "Lime"],
                Steps = [
                    "Soak rice noodles in warm water for 30 minutes, then drain.",
                    "Mix tamarind paste, fish sauce, and sugar to make the sauce.",
                    "Stir-fry shrimp in oil until pink, then set aside.",
                    "Scramble eggs in the same pan.",
                    "Add noodles and sauce, tossing to coat evenly.",
                    "Return shrimp, add bean sprouts and green onions.",
                    "Serve topped with crushed peanuts and lime wedges."
                ],
                Ratings = [4, 5, 4]
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh and zesty avocado dip, perfect as a snack or side.",
                Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
                Steps = [
                    "Halve and pit the avocados, scoop flesh into a bowl.",
                    "Mash with a fork to desired consistency.",
                    "Stir in lime juice, diced onion, jalapeño, tomato, and cilantro.",
                    "Season with salt and serve with tortilla chips."
                ],
                Ratings = [5, 4, 5, 5, 4, 5]
            },
            new Recipe
            {
                Id = 7, Title = "Miso Ramen", Category = "Asian",
                Description = "Hearty Japanese noodle soup with a rich miso broth.",
                Ingredients = ["Ramen noodles", "Miso paste", "Chicken broth", "Soy sauce", "Sesame oil", "Soft-boiled egg", "Corn", "Nori", "Green onions", "Chashu pork"],
                Steps = [
                    "Bring chicken broth to a simmer.",
                    "Whisk in miso paste, soy sauce, and sesame oil.",
                    "Cook ramen noodles according to package directions.",
                    "Place noodles in bowls and ladle broth over them.",
                    "Top with halved soft-boiled egg, corn, sliced chashu, nori, and green onions."
                ],
                Ratings = [5, 5, 4, 5, 5]
            },
            new Recipe
            {
                Id = 8, Title = "Butter Chicken", Category = "Indian",
                Description = "Tender chicken in a velvety, buttery tomato sauce.",
                Ingredients = ["Chicken thighs", "Butter", "Tomato purée", "Cream", "Garam masala", "Cumin", "Chili powder", "Garlic", "Ginger", "Fenugreek leaves"],
                Steps = [
                    "Marinate chicken in yogurt and spices for 1 hour.",
                    "Sear the chicken in butter until browned.",
                    "Sauté garlic and ginger in butter, add spices.",
                    "Add tomato purée and simmer for 20 minutes.",
                    "Stir in cream and fenugreek leaves.",
                    "Add chicken and simmer until cooked through.",
                    "Serve with steamed basmati rice or naan."
                ],
                Ratings = [5, 4, 5]
            },
        ];
        _nextId = 9;
    }

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public List<Recipe> GetAll() => _recipes;

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int rating)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && rating is >= 1 and <= 5)
        {
            recipe.Ratings.Add(rating);
        }
    }
}

