@rendermode InteractiveServer

<div class="star-rating d-inline-flex align-items-center">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= (_hoverRating ?? CurrentRating) ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => _hoverRating = star"
              @onmouseout="() => _hoverRating = null"
              role="button"
              title="Rate @star star@(star > 1 ? "s" : "")">
            ★
        </span>
    }
    @if (AverageRating > 0)
    {
        <span class="ms-2 text-muted small">
            @AverageRating.ToString("0.0") (@RatingCount @(RatingCount == 1 ? "rating" : "ratings"))
        </span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }
    [Parameter] public EventCallback<int> OnRate { get; set; }

    private int CurrentRating { get; set; }
    private int? _hoverRating;

    private async Task Rate(int rating)
    {
        CurrentRating = rating;
        await OnRate.InvokeAsync(rating);
    }
}

.star-rating .star {
    font-size: 1.5rem;
    color: #ccc;
    cursor: pointer;
    transition: color 0.15s;
    user-select: none;
}

.star-rating .star:hover,
.star-rating .star.filled {
    color: #ffc107;
}

